var a = [1, 2, 2, 3, 4];
var inB = new Set([2, 4, 4, 6]);
var result = [];
a.forEach(function (x) {
  if (inB.has(x) && result.indexOf(x) === -1) {
    result.push(x);
  }
});
console.log(result);
